using System.IO;
using System.Text.Json;
using Inferpal.Localization;
using Inferpal.Services.Execution;
using Inferpal.Services.Tools;
using Xunit;

namespace Inferpal.Tests;

/// <summary>
/// <c>replace_in_files</c>: one call and one approval for a change across many files, all or nothing, every file backed up,
/// generated files and documents left as they are, nothing written on a dry run, a refused card or past the file cap.
/// </summary>
public sealed class ReplaceInFilesToolTests : IDisposable
{
    private readonly string _root = Directory.CreateTempSubdirectory("inferpal-replace-").FullName;

    public void Dispose()
    {
        try { Directory.Delete(_root, recursive: true); } catch { /* best-effort cleanup */ }
    }

    private string Write(string relative, string content)
    {
        var path = Path.Combine(_root, relative);
        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        File.WriteAllText(path, content);
        return path;
    }

    private sealed class Spy(bool approve = true) : IApprovalService
    {
        public int Asked;
        public string? Details, Subject;
        public Task<bool> RequestApprovalAsync(string toolName, string details, CancellationToken ct, string? subject = null,
                                               Services.CodeActions.DiffInfo? diff = null, bool forcePrompt = false)
        {
            Asked++;
            Details = details;
            Subject = subject;
            return Task.FromResult(approve);
        }
    }

    private async Task<(string Said, Spy Spy, FileHistoryService History)> RunAsync(object args, bool approve = true)
    {
        var spy = new Spy(approve);
        var history = new FileHistoryService();
        using var doc = JsonDocument.Parse(JsonSerializer.Serialize(args));
        var said = await new ReplaceInFilesTool(spy, history, () => _root).ExecuteAsync(doc.RootElement.Clone(), default);
        return (said, spy, history);
    }

    [Fact]
    public async Task EveryFileThatHoldsTheText_IsChanged_InOneApproval()
    {
        var a = Write("src/A.cs", "var url = \"http://old.host/api\";\n");
        var b = Write("src/sub/B.cs", "// old.host\nCall(\"old.host\");\n");
        var c = Write("src/C.cs", "nothing here\n");

        var (said, spy, _) = await RunAsync(new { find = "old.host", replace = "new.host" });

        Assert.Equal(1, spy.Asked);
        Assert.Contains("new.host", File.ReadAllText(a));
        Assert.Equal("// new.host\nCall(\"new.host\");\n", File.ReadAllText(b));
        Assert.Equal("nothing here\n", File.ReadAllText(c));
        Assert.Contains("3 occurrence(s) in 2 file(s)", said);
        Assert.Contains("A.cs", spy.Subject);   // judged on every path it writes
        Assert.Contains("B.cs", spy.Subject);
        Assert.DoesNotContain("C.cs", spy.Subject!);
    }

    [Fact]
    public async Task ARegex_UsesItsGroups_AndTheTextDefault_IsExactAndCaseSensitive()
    {
        var f = Write("a.txt", "v1.2 V1.2 v1.3\n");

        await RunAsync(new { find = @"v(\d)\.(\d)", replace = "v$1_$2", regex = true });
        Assert.Equal("v1_2 V1.2 v1_3\n", File.ReadAllText(f));

        await RunAsync(new { find = "V1.2", replace = "X" });
        Assert.Equal("v1_2 X v1_3\n", File.ReadAllText(f));
    }

    [Fact]
    public async Task ADryRun_ARefusedCard_AndNoMatch_WriteNothing()
    {
        var f = Write("a.txt", "keep me\n");

        var (dry, drySpy, _) = await RunAsync(new { find = "keep", replace = "drop", dry_run = true });
        Assert.Contains("Dry run", dry);
        Assert.Equal(0, drySpy.Asked);

        var (refused, _, _) = await RunAsync(new { find = "keep", replace = "drop" }, approve: false);
        Assert.Equal(Strings.DiffCancelled, refused);

        var (none, noneSpy, _) = await RunAsync(new { find = "absent", replace = "x" });
        Assert.Contains("Nothing was changed", none);
        Assert.Equal(0, noneSpy.Asked);

        Assert.Equal("keep me\n", File.ReadAllText(f));
    }

    [Fact]
    public async Task AGeneratedFile_IsLeftAsItIs_AndSaid()
    {
        var gen = Write("Properties/Resources.Designer.cs", "// <auto-generated />\nclass R { string s = \"old\"; }\n");
        var own = Write("Own.cs", "class O { string s = \"old\"; }\n");

        var (said, _, _) = await RunAsync(new { find = "\"old\"", replace = "\"new\"" });

        Assert.Contains("\"old\"", File.ReadAllText(gen));
        Assert.Contains("\"new\"", File.ReadAllText(own));
        Assert.Contains("1 generated file(s) left as they are", said);
    }

    [Fact]
    public async Task PastTheFileCap_NothingIsWritten()
    {
        for (var i = 0; i <= ReplaceInFilesTool.MaxFiles; i++) Write($"f{i}.txt", "x\n");

        var (said, spy, _) = await RunAsync(new { find = "x", replace = "y" });

        Assert.StartsWith("Error:", said);
        Assert.Equal(0, spy.Asked);
        Assert.Equal("x\n", File.ReadAllText(Path.Combine(_root, "f0.txt")));
    }

    [Fact]
    public async Task AnInvalidRegex_IsRefused_BeforeAnyFileIsRead()
    {
        Write("a.txt", "(\n");
        var (said, spy, _) = await RunAsync(new { find = "(", replace = "", regex = true });
        Assert.Contains("not a valid regular expression", said);
        Assert.Equal(0, spy.Asked);
    }

    [Fact]
    public async Task ALinkedFileLeadingOutside_IsLeftAsItIs_AndSaid()
    {
        var outsideDir = Directory.CreateTempSubdirectory("inferpal-replace-outside-").FullName;
        try
        {
            var target = Path.Combine(outsideDir, "profile.txt");
            File.WriteAllText(target, "old value\n");
            try { File.CreateSymbolicLink(Path.Combine(_root, "notes.txt"), target); }
            catch (Exception ex) when (ex is IOException or UnauthorizedAccessException)
            {
                return;   // undecided here: this machine cannot create links without a privilege
            }
            Write("own.txt", "old value\n");

            var (said, _, _) = await RunAsync(new { find = "old", replace = "new" });

            Assert.Equal("old value\n", File.ReadAllText(target));
            Assert.Equal("new value\n", File.ReadAllText(Path.Combine(_root, "own.txt")));
            Assert.Contains("1 linked file(s) leading outside the workspace", said);
        }
        finally { try { Directory.Delete(outsideDir, recursive: true); } catch { } }
    }

    [Fact]
    public async Task AMultiLineText_FindsACrlfFile_AndKeepsItsLineBreaks()
    {
        var f = Path.Combine(_root, "win.cs");
        File.WriteAllText(f, "int a;\r\nint b;\r\nint c;\r\n");

        await RunAsync(new { find = "int a;\nint b;", replace = "int a;\nint b2;\nint b3;" });

        Assert.Equal("int a;\r\nint b2;\r\nint b3;\r\nint c;\r\n", File.ReadAllText(f));
    }

    [Theory]
    [InlineData("$_")]
    [InlineData("x$`")]
    [InlineData("$'")]
    [InlineData("$+")]
    public async Task ARegexReplacementThatWouldCopyTheFile_IsRefused(string replacement)
    {
        var f = Write("a.txt", "abc\n");
        var (said, spy, _) = await RunAsync(new { find = "b", replace = replacement, regex = true });
        Assert.StartsWith("Error: the replacement holds", said);
        Assert.Equal(0, spy.Asked);
        Assert.Equal("abc\n", File.ReadAllText(f));
    }

    [Fact]
    public async Task ARegexReplacement_KeepsACrlfFilesLineBreaks()
    {
        var f = Path.Combine(_root, "win.cs");
        File.WriteAllText(f, "foo\r\nend\r\n");
        await RunAsync(new { find = "foo\\r?$", replace = "foo\nbar", regex = true });
        Assert.Equal("foo\r\nbar\r\nend\r\n", File.ReadAllText(f));
    }

    [Fact]
    public async Task ADoubledDollar_IsALiteralDollar_InARegexReplacement()
    {
        var f = Write("a.txt", "price\n");
        await RunAsync(new { find = "price", replace = "$$_price", regex = true });
        Assert.Equal("$_price\n", File.ReadAllText(f));
    }

    [Fact]
    public async Task APathOutsideTheWorkspace_IsRefused()
    {
        await Assert.ThrowsAnyAsync<Exception>(() => RunAsync(new { find = "a", replace = "b", path = "../.." }));
    }
}
